INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob jede Webseite immer mit einem bestimmten Tag beginnt?', 2, '[{"text": "Ja", "correct": true, "because": "<!DOCTYPE> definiert das Dokument"}, {"text": "Nein", "correct": false, "because": "Standard für gültige Seiten"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Element ist entscheidend, um eine Überschrift auf einer Seite zu setzen?', 3, '[{"text": "<h1>", "correct": true, "because": "Markiert Hauptüberschrift"}, {"text": "<p>", "correct": false, "because": "Nur für Absätze"}, {"text": "<div>", "correct": false, "because": "Allgemeiner Container"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Tags sind für eine einfache Webseite essenziell?', 5, '[{"text": "<html>", "correct": true, "because": "Wurzelelement"}, {"text": "<head>", "correct": true, "because": "Metadaten und Titel"}, {"text": "<body>", "correct": true, "because": "Sichtbarer Inhalt"}, {"text": "<span>", "correct": false, "because": "Nur für Inline"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Tags müssen immer geschlossen werden. b) Attribute sind optional.', 3, '[{"text": "Nur b) stimmt", "correct": true, "because": "Einige Tags sind selbstschließend"}, {"text": "Beides stimmt", "correct": false, "because": "a) ist falsch"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "b) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich, wenn ich eine Seite strukturiere?', 4, '[{"text": "Semantische Tags", "correct": false, "because": "Verbessern Zugänglichkeit"}, {"text": "Verschachtelung", "correct": false, "because": "Definiert Struktur"}, {"text": "Schriftfarbe", "correct": true, "because": "Styling, nicht Struktur"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass jede Seite nur Text enthalten kann. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Bilder und mehr möglich"}, {"text": "Ja", "correct": false, "because": "Multimedia wird unterstützt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Tag wähle ich, um ein Bild einzubinden?', 3, '[{"text": "<img>", "correct": true, "because": "Fügt Bilder ein"}, {"text": "<a>", "correct": false, "because": "Nur für Links"}, {"text": "<p>", "correct": false, "because": "Für Text"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Attribute sind für einen Link wichtig?', 5, '[{"text": "href", "correct": true, "because": "Ziel des Links"}, {"text": "target", "correct": true, "because": "Öffnungsverhalten"}, {"text": "color", "correct": false, "because": "Styling, nicht Funktion"}, {"text": "size", "correct": false, "because": "Kein Standardattribut"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass a) <div> semantisch ist und b) <section> für Inhalte besser ist. Stimmt das?', 3, '[{"text": "Nur b) stimmt", "correct": true, "because": "<div> ist neutral"}, {"text": "Beides stimmt", "correct": false, "because": "a) ist falsch"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "b) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht, um eine einfache Seite zu erstellen?', 4, '[{"text": "<html>", "correct": false, "because": "Wurzelelement nötig"}, {"text": "<body>", "correct": false, "because": "Inhalt erforderlich"}, {"text": "<script>", "correct": true, "because": "Optional für Interaktivität"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Muss jede Seite einen Titel haben?', 2, '[{"text": "Ja", "correct": true, "because": "<title> ist Standard"}, {"text": "Nein", "correct": false, "because": "Empfohlen für Zugänglichkeit"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Tags helfen bei der Strukturierung?', 4, '[{"text": "<header>", "correct": true, "because": "Kopfzeile definiert"}, {"text": "<footer>", "correct": true, "because": "Fußzeile markiert"}, {"text": "<img>", "correct": false, "because": "Nur Inhalt"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass es nur für Text geeignet ist. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Unterstützt Multimedia"}, {"text": "Ja", "correct": false, "because": "Vielseitig einsetzbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit semantischen Tags?', 3, '[{"text": "Bessere Zugänglichkeit", "correct": true, "because": "Erleichtert Screenreader"}, {"text": "Schnellere Ladezeit", "correct": false, "because": "Kein direkter Effekt"}, {"text": "Mehr Farben", "correct": false, "because": "Styling separat"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) <meta> gehört in den Kopf. b) <body> ist optional.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "<body> ist essenziell"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rolle spielt das <form>-Tag?', 4, '[{"text": "Eingaben sammeln", "correct": true, "because": "Erlaubt Nutzerinteraktion"}, {"text": "Bilder anzeigen", "correct": false, "because": "Falsche Funktion"}, {"text": "Text formatieren", "correct": false, "because": "Nicht dafür gedacht"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob jedes Tag ein Attribut braucht?', 2, '[{"text": "Nein", "correct": true, "because": "Viele funktionieren ohne"}, {"text": "Ja", "correct": false, "because": "Optional je nach Tag"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet die Version 5?', 5, '[{"text": "Semantische Tags", "correct": true, "because": "Bessere Struktur"}, {"text": "Multimedia-Unterstützung", "correct": true, "because": "Video und Audio"}, {"text": "Schnellere Ladezeit", "correct": false, "because": "Abhängig von Server"}, {"text": "Automatisches Styling", "correct": false, "because": "CSS nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist <table> für Layouts gedacht?', 3, '[{"text": "Nein", "correct": true, "because": "Nur für tabellarische Daten"}, {"text": "Ja", "correct": false, "because": "CSS ist moderner Ansatz"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Tag wähle ich für eine Liste?', 4, '[{"text": "<ul>", "correct": true, "because": "Ungeordnete Liste"}, {"text": "<p>", "correct": false, "because": "Nur Absatz"}, {"text": "<div>", "correct": false, "because": "Allgemeiner Container"}]');
